import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.D3oaa6bG.js";const h=JSON.parse('{"title":"Services","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage/services.md","filePath":"guide/usage/services.md","lastUpdated":null}'),s={name:"guide/usage/services.md"};function c(i,e,n,d,p,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h1><p>Services are additional offerings for a product (e. g. extended warranty, on-site installation).</p><p>You can attach any number of services to a product on the edit product form in the backend (cart section).</p><p>If a product with attached services is added to the cart, a modal appears where service options can or must be selected.</p><p>Each service needs at least one option. Each option has a price. A service can be specified to be required when a certain product is added to the cart.</p><p>By default, only one of the provided options can be selected. By changing the <a href="https://github.com/wintercms/wn-mall-plugin/blob/317508f6bcbb7d280e96e379d1cec9b0636dc207/components/product/servicemodal.htm#L36" target="_blank" rel="noreferrer">type of the <code>radio</code> inputs to <code>checkbox</code></a>, a user will be able to select multiple options for a single service.</p>',6)])])}const f=t(s,[["render",c]]);export{h as __pageData,f as default};
